-- ----------------------------
-- Table structure for drop_data
-- ----------------------------
DROP TABLE IF EXISTS `drop_data`;
CREATE TABLE `drop_data`  (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `dropperid` int NOT NULL,
  `itemid` int NOT NULL DEFAULT 0,
  `minimum_quantity` int NOT NULL DEFAULT 1,
  `maximum_quantity` int NOT NULL DEFAULT 1,
  `questid` int NOT NULL DEFAULT 0,
  `chance` int NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_dropper_item`(`dropperid`, `itemid`) USING BTREE
) ENGINE = MyISAM AUTO_INCREMENT = 36263 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci ROW_FORMAT = FIXED;

